def S(n):
    """Calculates the sum of the digits of n."""
    return sum(int(d) for d in str(n))

def check_condition(n):
    """Checks if S(n)S(n+1)...S(n+37) is NOT a multiple of 11."""
    for k in range(n, n + 38):
        if S(k) % 11 == 0:
            return False  # Found a multiple of 11
    return True  # No multiple of 11 found in the range

# Start searching from n=1, but based on previous findings, 
# we suspect the smallest n might be large. Let's search up to a manageable limit first, say 5 million.
print("Starting systematic search for the smallest n...")
limit = 5_000_000
found_n = -1

for n in range(1, limit + 1):
    if check_condition(n):
        found_n = n
        break

if found_n != -1:
    print(f"Smallest n found within the limit: {found_n}")
else:
    print(f"No solution found up to the limit of {limit}. Solution likely larger or requires more powerful search.")

def sum_digits(n):
    s = 0
    while n:
        s += n % 10
        n //= 10
    return s

def check_condition(n):
    for k in range(n, n + 38):
        s_k = sum_digits(k)
        if s_k % 11 == 0:
            return False
    return True

